css:
.sl-cta-bento {
    padding-block: clamp(3rem, 6vw, 5.5rem);
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-cta-bento .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-cta-bento .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-cta-bento .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-cta-bento.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-cta-bento .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; }
.sl-cta-bento .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-cta-bento .sl-bento-main {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text, #ffffff);
}
.sl-cta-bento .sl-bento-main-title {
    color: var(--smartlearn-btn-text, #ffffff);
}
.sl-cta-bento .sl-bento-main-subtitle {
    color: var(--smartlearn-btn-text, #ffffff);
    opacity: 0.9;
}
.sl-cta-bento .sl-bento-deco {
    width: 300px;
    height: 300px;
    top: -100px;
    inset-inline-end: -100px;
    background-color: var(--smartlearn-btn-text, #ffffff);
    opacity: 0.1;
    pointer-events: none;
}
.sl-cta-bento .sl-bento-main-btn {
    background-color: var(--smartlearn-bg) !important;
    color: var(--smartlearn-text) !important;
    border: 2px solid transparent !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.sl-cta-bento .sl-bento-main-btn:hover,
.sl-cta-bento .sl-bento-main-btn:focus-visible {
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.15);
    background-color: var(--smartlearn-card-bg) !important;
    color: var(--smartlearn-text) !important;
}
.sl-cta-bento .sl-bento-main-btn:focus-visible {
    outline: 2px solid var(--smartlearn-btn-text, #ffffff);
    outline-offset: 2px;
}
.sl-cta-bento .sl-bento-icon-primary {
    width: 56px;
    height: 56px;
    background-color: var(--smartlearn-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
}
.sl-cta-bento .sl-bento-icon-muted {
    width: 48px;
    height: 48px;
}
.sl-cta-bento .sl-learn-more::after {
    content: " →";
    display: inline-block;
}
[dir="rtl"] .sl-cta-bento .sl-learn-more::after {
    transform: scaleX(-1);
}
.sl-cta-bento .sl-hover-lift {
    transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.sl-cta-bento .sl-hover-lift:hover,
.sl-cta-bento .sl-hover-lift:focus-within {
    transform: translateY(-4px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08) !important;
    border-color: var(--smartlearn-primary) !important;
}
.sl-cta-bento a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-bento .sl-bento-main-btn,
    .sl-cta-bento .sl-hover-lift { transition: none; }
    .sl-cta-bento .sl-bento-main-btn:hover,
    .sl-cta-bento .sl-bento-main-btn:focus-visible,
    .sl-cta-bento .sl-hover-lift:hover,
    .sl-cta-bento .sl-hover-lift:focus-within { transform: none; }
}
